output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts must not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not move into a single-file aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_cart_after_parking_at_aisle_mouth",
    "text": "If a cart is parked at the mouth of a pedestrian-only shelf aisle, it must later be retrieved before leaving.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCartAtPedestrianAisleMouth": {
          "pre": {
            "and": [
              "pedestrianAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtPedestrianAisleMouth": {
          "pre": {
            "and": [
              "pedestrianAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCartAtPedestrianAisleMouth",
      "discharge": "retrieveCartAtPedestrianAisleMouth"
    }
  },
  {
    "id": "return_to_cart_after_on_foot_browsing",
    "text": "After interacting with shelves on foot inside a single-file aisle, the agent must return to and pick up the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "onFootShelfInteractionInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootShelfInteractionInSingleFileAisle",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "cart_required_for_wide_shelf_service",
    "text": "Shelf interactions outside single-file pedestrian aisles must be performed with a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartServiceShelfZone": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartServiceShelfZone",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "park_carts_only_in_open_cross_aisles",
    "text": "A cart may only be left behind in a wide open cross-aisle rather than in a narrow or shelf-adjacent area.",
    "abstraction": {
      "state_properties": {
        "openCrossAisleParkingZone": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "openCrossAisleParkingZone"
          }
        ]
      }
    }
  },
  {
    "id": "no_push_north_from_pedestrian_aisle_mouth",
    "text": "From the mouth of a pedestrian-only shelf aisle, a cart must not be pushed north into the aisle.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "pushNorthFromPedestrianAisleMouth": {
          "pre": {
            "and": [
              "pedestrianAisleMouth",
              "hasCart",
              "N"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushNorthFromPedestrianAisleMouth"
    }
  },
  {
    "id": "single_file_aisles_are_vertical_lanes",
    "text": "Inside single-file shelf aisles, movement should remain along the aisle rather than cutting sideways.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          {
            "or": [
              "E",
              "W"
            ]
          }
        ]
      }
    }
  }
]
